// src/pages/BlogPage/BlogPage.jsx
import React, { useState, useEffect } from 'react';
import { FaTag, FaHeart, FaStar, FaLaptop, FaPlane, FaShoppingCart, FaCalendarAlt, FaEllipsisH } from 'react-icons/fa';
import styles from './BlogPage.module.css';
import BlogCard from './BlogCard';
import TrendingSection from './TrendingSection';

const categories = [
  { id: 'budget', label: 'Budget', icon: <FaTag /> },
  { id: 'beauty', label: 'Beauty', icon: <FaHeart /> },
  { id: 'fashion', label: 'Fashion', icon: <FaStar /> },
  { id: 'home', label: 'Home', icon: <FaLaptop /> },
  { id: 'travel', label: 'Travel', icon: <FaPlane /> },
  { id: 'deals', label: 'Deals', icon: <FaShoppingCart /> },
  { id: 'calendar', label: 'Calendar', icon: <FaCalendarAlt /> },
  { id: 'more', label: 'More', icon: <FaEllipsisH /> },
];

export const BlogPage = () => {
  const [activeCategory, setActiveCategory] = useState('all');
  const [posts, setPosts] = useState([]);
  const [newBlog, setNewBlog] = useState({
    title: '',
    category: 'budget',
    excerpt: '',
    image: '',
  });
  const [error, setError] = useState(null);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  useEffect(() => {
    fetchBlogs();
    checkAuthStatus();
  }, []);

  // Check if user is logged in and has admin privileges
  const checkAuthStatus = () => {
    const token = localStorage.getItem('token');
    const userInfo = localStorage.getItem('userInfo');

    if (token) {
      setIsLoggedIn(true);

      // Check if user has admin role
      try {
        const user = JSON.parse(userInfo);
        if (user && user.role === 'admin') {
          setIsAdmin(true);
        }
      } catch (err) {
        console.error('Error parsing user info:', err);
      }
    }
  };

  const fetchBlogs = async () => {
    try {
      // Get blogs is a public endpoint, but we'll include the token if available
      // to potentially get admin-only blogs in the future
      const token = localStorage.getItem('token');
      const headers = token ? { 'Authorization': `Bearer ${token}` } : {};

      const response = await fetch('http://localhost:5000/api/blogs', { headers });

      if (response.ok) {
        const data = await response.json();
        setPosts(data.data || data); // Handle both response formats
        setError(null);
      } else {
        setError('Failed to load blogs');
      }
    } catch (err) {
      console.error('Error fetching blogs:', err);
      setError('Failed to load blogs: ' + (err.message || 'Unknown error'));
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setNewBlog((prev) => ({ ...prev, [name]: value }));
  };

  const handleAddBlog = async (e) => {
    e.preventDefault();
    try {
      // Get the authentication token from localStorage
      const token = localStorage.getItem('token');

      if (!token) {
        setError('Authentication required. Please log in as an admin.');
        return;
      }

      const response = await fetch('http://localhost:5000/api/blogs', {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(newBlog),
      });

      if (response.ok) {
        const addedBlog = await response.json();
        setPosts([...posts, addedBlog]);
        setNewBlog({ title: '', category: 'budget', excerpt: '', image: '' });
        setError(null); // Clear any previous errors
      } else if (response.status === 401) {
        setError('Authentication required. Please log in as an admin.');
      } else if (response.status === 403) {
        setError('Admin privileges required to add blog posts.');
      } else {
        const errorData = await response.json();
        setError(errorData.message || 'Failed to add blog');
      }
    } catch (err) {
      console.error('Error adding blog:', err);
      setError('Error adding blog: ' + (err.message || 'Unknown error'));
    }
  };

  const handleDeleteBlog = async (id) => {
    try {
      // Get the authentication token from localStorage
      const token = localStorage.getItem('token');

      if (!token) {
        setError('Authentication required. Please log in as an admin.');
        return;
      }

      const response = await fetch(`http://localhost:5000/api/blogs/${id}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });

      if (response.ok) {
        setPosts(posts.filter(post => post._id !== id));
        setError(null); // Clear any previous errors
      } else if (response.status === 401) {
        setError('Authentication required. Please log in as an admin.');
      } else if (response.status === 403) {
        setError('Admin privileges required to delete blog posts.');
      } else {
        const errorData = await response.json();
        setError(errorData.message || 'Failed to delete blog');
      }
    } catch (err) {
      console.error('Error deleting blog:', err);
      setError('Error deleting blog: ' + (err.message || 'Unknown error'));
    }
  };

  // Ensure posts is an array before filtering
  const filteredPosts = Array.isArray(posts) 
    ? (activeCategory === 'all' 
        ? posts 
        : posts.filter(post => post.category === activeCategory))
    : [];

  return (
    <div className={styles.blogPage}>
      <div className={styles.categoryNav}>
        {categories.map((cat) => (
          <button
            key={cat.id}
            className={`${styles.categoryButton} ${activeCategory === cat.id && styles.active}`}
            onClick={() => setActiveCategory(cat.id === 'more' ? 'all' : cat.id)}
          >
            {cat.icon} {cat.label}
          </button>
        ))}
        <p className={styles.disclaimer}>
          Every product and brand is selected by CashHeros's editors. We may earn a commission on the items you choose to buy. Learn more.
        </p>
      </div>

      {isLoggedIn && isAdmin ? (
        <div className={styles.uploadForm}>
          <h2>Add New Blog</h2>
          {error && <p className={styles.error}>{error}</p>}
          <form onSubmit={handleAddBlog}>
            <input type="text" name="title" placeholder="Title" value={newBlog.title} onChange={handleInputChange} required />
            <select name="category" value={newBlog.category} onChange={handleInputChange}>
              {categories.slice(0, -1).map((cat) => (
                <option key={cat.id} value={cat.id}>{cat.label}</option>
              ))}
            </select>
            <input type="text" name="excerpt" placeholder="Excerpt" value={newBlog.excerpt} onChange={handleInputChange} required />
            <input type="url" name="image" placeholder="Image URL" value={newBlog.image} onChange={handleInputChange} required />
            <button type="submit">Add Blog</button>
          </form>
        </div>
      ) : (
        <div className={styles.uploadForm}>
          <h2>Blog Management</h2>
          {error && <p className={styles.error}>{error}</p>}
          <p className={styles.adminMessage}>
            {isLoggedIn 
              ? "You need admin privileges to add or manage blog posts." 
              : "Please log in as an admin to add or manage blog posts."}
          </p>
        </div>
      )}

      <div className={styles.mainContent}>
        <div className={styles.blogCards}>
          {categories.map((cat) => {
            // Skip the "more" category
            if (cat.id === 'more') return null;

            // Get posts for this category
            const catPosts = filteredPosts.filter(post => post.category === cat.id);

            // Skip rendering if no posts in this category
            if (catPosts.length === 0) return null;

            return (
              <div key={cat.id} className={styles.categorySection}>
                <h2 className={styles.categoryTitle}>{cat.label}</h2>
                <div className={styles.cardsGrid}>
                  {catPosts.map((post) => (
                    <BlogCard key={post._id} {...post} id={post._id} onDelete={handleDeleteBlog} />
                  ))}
                </div>
              </div>
            );
          })}
        </div>
        <TrendingSection posts={Array.isArray(posts) ? posts.slice(0, 5) : []} />
      </div>
    </div>
  );
};
